package com.queueless.controller;
import com.queueless.dao.QueueDAO; import com.queueless.model.QueueEntry; import com.queueless.util.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/api/queue/action") public class QueueActionServlet extends HttpServlet{
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{if(AuthUtil.require(req,res)==null)return;res.setContentType("application/json;charset=UTF-8");try{String a=req.getParameter("action");QueueDAO d=new QueueDAO();if("next".equals(a)){QueueEntry q=d.callNext(Long.parseLong(req.getParameter("serviceId")));res.getWriter().write("{\"success\":true,\"message\":\"Now serving "+JsonUtil.esc(q.token)+".\",\"token\":\""+q.token+"\"}");}else{long id=Long.parseLong(req.getParameter("id"));d.action(id,a);QueueEntry now=null;try{now=d.current(Long.parseLong(req.getParameter("serviceId")));}catch(Exception ignored){}String msg=(now!=null&&!("cancel".equals(a)))?"Next customer "+now.token+" is now being served.":"Queue updated successfully.";res.getWriter().write(JsonUtil.ok(msg));}}catch(Exception e){res.setStatus(400);res.getWriter().write(JsonUtil.error(e.getMessage()==null?"Queue action failed.":e.getMessage()));}}
}
